function readSavedLanguage(initial?:OfficeUiLanguage):OfficeUiLanguage{
  if(typeof window==="undefined")return initial||"en";
  const saved=parseOfficeUiLanguage(window.localStorage.getItem(STORAGE_KEY));
  const lang=saved||initial||"en";
  document.documentElement.lang=lang;
  persistOfficeLanguageCookie(lang);
  return lang;
}

export function OfficeI18nProvider({children,initialLanguage}:{children:React.ReactNode;initialLanguage?:OfficeUiLanguage}){
  const [language,setLanguageState]=useState<OfficeUiLanguage>(()=>readSavedLanguage(initialLanguage));

  useEffect(()=>{
    const saved=readSavedLanguage(initialLanguage);
    setLanguageState(saved);
    document.documentElement.lang=saved;
  },[initialLanguage]);

  const setLanguage=(value:OfficeUiLanguage)=>{
    setLanguageState(value);
    window.localStorage.setItem(STORAGE_KEY,value);
    persistOfficeLanguageCookie(value);
    document.documentElement.lang=value;
    window.dispatchEvent(new CustomEvent(OFFICE_LANGUAGE_EVENT,{detail:value}));
  };

  const value=useMemo<I18nContextValue>(()=>({
    language,setLanguage,
    t:(key,fallback)=>{
      const core=(CORE_TRANSLATIONS as unknown as Record<OfficeUiLanguage,Record<string,string>>);
      const legacy=(LEGACY_RUNTIME_TRANSLATIONS as unknown as Record<OfficeUiLanguage,Record<string,string>>);
      const localized=core[language]?.[key]??legacy[language]?.[key]??OFFICE_DICTIONARIES[language]?.[key];
      return localized??core.en?.[key]??legacy.en?.[key]??OFFICE_DICTIONARIES.en?.[key]??fallback??key;
    }
  }),[language]);

  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function useOfficeI18n(){
  const value=useContext(Context);
  if(!value)throw new Error("useOfficeI18n must be used inside OfficeI18nProvider");
  return value;
}
